const money = formatCOP;
// wa.me necesita solo dígitos con indicativo; un celular colombiano de 10 dígitos recibe el 57.
export const whatsappDigits = value => {const digits=String(value||'').replace(/\D/g,'');return /^3\d{9}$/.test(digits)?'57'+digits:digits.length>=11&&digits.length<=15?digits:'';};
export const whatsappLink = (number,message) => {const digits=whatsappDigits(number);return digits?'https://wa.me/'+digits+'?text='+encodeURIComponent(message):'';};
const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dayLabel = value => value ? formatDate(String(value).slice(0,10),'Sin definir') : 'Sin definir';
const timeLabel = value => value ? formatDateTime(value,'Sin cambios registrados') : 'Sin cambios registrados';
const text = value => String(value||'');
const initials = name => text(name).trim().split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase()||'E';
const normalize = value => text(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const roleLabel = role => ['admin','administrator','administrador'].includes(role)?'Administrador':'Vendedor';
function plusMonth(value){const [year,month,day]=value.split('-').map(Number);const end=new Date(Date.UTC(year,month+1,0));return [end.getUTCFullYear(),String(end.getUTCMonth()+1).padStart(2,'0'),String(Math.min(day,end.getUTCDate())).padStart(2,'0')].join('-');}
// BE-37: plan de la empresa (vacío = sin límite; sin plan = todas las funciones).
const planForm=company=>{const plan=companyPlan(company);return {maxUsers:plan.maxUsers??'',maxProducts:plan.maxProducts??'',maxPhotos:plan.maxPhotos??'',features:[...plan.features]}};
const limitText=(used,max)=>max==null?`${used} · sin límite`:`${used} de ${max}`;
export function PlanSummary({company,onEdit}){
 const plan=companyPlan(company),usage=company.usage||{};
 return <section className="ow-panel"><div className="ow-panel-heading"><h2>Plan y límites</h2>{onEdit&&<button type="button" className="ow-button ow-secondary" onClick={onEdit}>Editar plan</button>}</div>
  <dl className="ow-detail-data"><div><dt>Usuarios activos</dt><dd>{limitText(Number(usage.users)||0,plan.maxUsers)}</dd></div><div><dt>Productos</dt><dd>{limitText(Number(usage.products)||0,plan.maxProducts)}</dd></div><div><dt>Fotos de productos</dt><dd>{limitText(Number(usage.photos)||0,plan.maxPhotos)}</dd></div>
   <div><dt>Funciones incluidas</dt><dd>{plan.features.length?PLAN_FEATURES.filter(([key])=>plan.features.includes(key)).map(([,label])=>label).join(' · '):'Solo las funciones básicas'}</dd></div></dl></section>;
}
function companyName(company){return company.name||company.nombre||company.companyName||'Empresa';}
function companyStart(company){return company.startDate||company.contractStart||company.inicio||'';}
function companyEnd(company){return company.endDate||company.contractEnd||company.fin||'';}
function companyFee(company){return company.monthlyFee??company.fee??company.valorMensual??0;}
function manualBlock(company){return company.manualDisabled===true||company.disabled===true||company.enabled===false||company.manualEnabled===false||company.status==='disabled';}
function statusOf(company){if(manualBlock(company))return {label:'Inhabilitada',className:'disabled'};const day=today(),start=companyStart(company),end=companyEnd(company);if(end&&end<day)return {label:'Vencida',className:'expired'};if(start&&start>day)return {label:'Próximamente',className:'scheduled'};return {label:'Activa',className:'active'};}
function daysRemaining(company){const end=companyEnd(company);if(!end)return null;return Math.round((Date.parse(end+'T12:00:00Z')-Date.parse(today()+'T12:00:00Z'))/86400000);}
function Icon({name,size=20}){const paths={plus:<path d="M12 5v14M5 12h14"/>,back:<path d="m15 18-6-6 6-6"/>,close:<path d="m6 6 12 12M6 18 18 6"/>,company:<><path d="M4 21V3h11v18M15 10h5v11M8 7h3M8 11h3M8 15h3M2 21h20"/></>,link:<><path d="m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/></>,copy:<><rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/></>,user:<><circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></>,eye:<><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></>,logout:<><path d="M9 4H4v16h5M13 8l4 4-4 4M8 12h12"/></>,search:<><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></>,check:<path d="m5 12 4 4L19 6"/>,warning:<><path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5M12 17v.1"/></>};return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]||paths.company}</svg>;}
function Field({label,children,hint}){return <label className="ow-field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
function Password({value,onChange,label='Contraseña',required=true,minLength=PASSWORD_MIN_LENGTH,autoComplete='new-password'}){const [visible,setVisible]=useState(false);return <Field label={label} hint={PASSWORD_HELP}><span className="ow-password"><input type={visible?'text':'password'} value={value} onChange={onChange} required={required} minLength={minLength} pattern={PASSWORD_PATTERN} title={PASSWORD_HELP} maxLength={PASSWORD_MAX_LENGTH} autoComplete={autoComplete}/><button type="button" className="ow-icon-button" aria-label={visible?'Ocultar contraseña':'Mostrar contraseña'} onClick={()=>setVisible(v=>!v)}><Icon name="eye"/></button></span></Field>;}
function Modal({title,onClose,children,footer,busy}){
 return <Dialog title={title} onClose={onClose} footer={footer} busy={busy} backdropClassName="ow-modal-backdrop" className="ow-modal" bodyClassName="ow-modal-content" closeClassName="ow-icon-button" closeIcon={<Icon name="close"/>} initialFocus="input:not([disabled]):not([type=file]),select,textarea">{children}</Dialog>;
}
function Badge({company}){const status=statusOf(company);return <span className={'ow-badge ow-badge-'+status.className}>{status.label}</span>;}
function Logo({company,size='normal'}){const logo=company.logo||company.logoUrl;return <span className={'ow-company-logo ow-logo-'+size}>{logo?<img src={logo} alt={'Logo de '+companyName(company)}/>:initials(companyName(company))}</span>;}
function datePeriod(company){const days=daysRemaining(company);if(days===null)return 'Vigencia por definir';if(days<0)return `Venció hace ${Math.abs(days)} ${days===-1?'día':'días'}`;if(days===0)return 'Vence hoy';return `${days} ${days===1?'día restante':'días restantes'}`;}

const shiftDay=(value,days)=>{if(!value)return '';const point=new Date(value+'T12:00:00Z');point.setUTCDate(point.getUTCDate()+days);return point.toISOString().slice(0,10)};
export function billingMessagePreview(company,{payment=null,now}={}){
 const point=typeof now==='function'?now():now;
 const currentDay=point===undefined?today():typeof point==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(point)?point:new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(point));
 const endDate=companyEnd(company),reminderDate=shiftDay(endDate,-3),blockDate=shiftDay(endDate,1),greeting=company.contact||company.contactName||companyName(company);
 const paymentEnd=payment?.endDate||payment?.newEndDate||payment?.periodEnd||endDate;
 const reminderText=`Hola ${greeting}. Tu servicio de FRAGOLA SCORTA vence el ${dayLabel(endDate)}. Recuerda renovarlo para continuar utilizando la aplicación. Si ya realizaste el pago, comunícate con el propietario para confirmarlo.`;
 const paymentText=`Hola ${greeting}. Confirmamos tu pago de ${money(payment?.amount??payment?.importe??companyFee(company))}. Tu servicio de FRAGOLA SCORTA tiene vigencia hasta el ${dayLabel(paymentEnd)}.${manualBlock(company)?' Tu empresa conserva una suspensión manual; contacta al propietario para revisar el acceso.':''}`;
 return {endDate,reminderDate,blockDate,paymentEnd,reminderText,paymentText,currentDay,reminderDue:currentDay===reminderDate&&!manualBlock(company)};
}

// BE-20 / BE-32 / BE-33: uso por empresa, métricas comerciales y eventos de seguridad.
const securityLabels={login_failures:'Intentos fallidos de ingreso',owner_new_origin:'Ingreso del propietario desde un origen nuevo',support_start:'Inicio de acceso de soporte'};
const eventDetail=event=>[event.empresa,event.usuario&&'usuario '+event.usuario,event.intentos&&event.intentos+' intentos',event.motivo&&'motivo: '+event.motivo].filter(Boolean).join(' · ');
export function usageOf(company,now=today()){const usage=company.usage||{};const idle=!Number(usage.sales7d);return {lastLoginAt:usage.lastLoginAt||null,lastSaleAt:usage.lastSaleAt||null,sales7d:Number(usage.sales7d)||0,idle,now};}
export function MetricCards({metrics}){if(!metrics)return null;const cards=[['Ingreso mensual',money(metrics.mrr||0),'mrr'],['Activas',metrics.active||0,'active'],['En prueba',metrics.trial||0,'trial'],['Vencidas',metrics.expired||0,'expired'],['Suspendidas',metrics.disabled||0,'disabled'],['Bajas en 30 días',metrics.churn30d||0,'churn']];return <section className="ow-metrics" aria-label="Métricas de SCORTA">{cards.map(([label,value,key])=><div className={'ow-metric ow-metric-'+key} key={key}><span>{label}</span><strong>{value}</strong></div>)}</section>;}
// OPS-19: estado del servidor (solo lectura) a partir de GET /api/v2/owner/server-status.
const bytesLabel=value=>Number.isFinite(value)?(value>=1048576?(value/1048576).toFixed(1)+' MB':Math.max(1,Math.round(value/1024))+' KB'):'Sin dato';
const uptimeLabel=seconds=>{if(!Number.isFinite(seconds))return 'Sin dato';const d=Math.floor(seconds/86400),h=Math.floor(seconds%86400/3600),m=Math.floor(seconds%3600/60);return d?d+' d '+h+' h':h?h+' h '+m+' min':m+' min';};
const backupLabel=(backup,missing)=>!backup?.at?missing:(backup.ok?'Correcto':'Falló')+' · '+timeLabel(backup.at);
export function ServerStatusView({status}){
 if(!status)return null;const backups=status.backups||{};
 const rows=[['Versión',text(status.version)||'Sin dato'],['Activo desde',status.startedAt?timeLabel(status.startedAt)+' ('+uptimeLabel(status.uptimeSeconds)+')':'Sin dato'],['Disco usado',status.disk?.usedPct==null?'Sin dato':status.disk.usedPct+' %'],['Base de datos',bytesLabel(status.db?.sizeBytes)+' · estado '+bytesLabel(status.db?.stateBytes)],['Latencia API (p95)',status.latencyP95Ms==null?'Sin peticiones aún':status.latencyP95Ms+' ms'],['Respaldo local',backupLabel(backups.local,'Sin respaldo en este arranque')],['Respaldo externo',backupLabel(backups.offsite,backups.offsiteEnabled?'Pendiente del primer envío':'Desactivado')],['Alertas por correo',status.alertMail?'Activas':'Desactivadas']];
 const capacityWarning=status.capacityWarning??status.warning,offsiteWarning=status.offsiteBackup?.warning===true;
 return <><p className={capacityWarning||!status.ok?'ow-server-warning':'ow-server-ok'} role="status">{!status.ok?'La base de datos no responde correctamente.':capacityWarning?'Atención: el disco supera el 80 % o el estado supera 20 MB.':'Sin alertas de capacidad.'}</p>{offsiteWarning&&<p className="ow-server-warning" role="status">Atención: el respaldo externo está apagado en producción. Faltan variables: {(status.offsiteBackup.missing||[]).join(', ')||'ver OPERACION.md'}.</p>}<dl className="ow-detail-data">{rows.map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl></>;
}
export function ServerStatus(){
 const [status,setStatus]=useState(null),[error,setError]=useState(''),[loading,setLoading]=useState(false);
 const load=async()=>{setLoading(true);setError('');try{const response=await fetch('/api/v2/owner/server-status',{credentials:'same-origin'});let body=null;try{body=await response.json()}catch{}if(!response.ok||!body?.status)throw Error(body?.error||'No se pudo consultar el estado del servidor.');setStatus(body.status)}catch(failure){setError(failure.message||'No se pudo consultar el estado del servidor.')}finally{setLoading(false)}};
 useEffect(()=>{load()},[]);
 return <section className="ow-panel ow-server" aria-labelledby="ow-server-title"><div className="ow-panel-heading"><h2 id="ow-server-title">Estado del servidor</h2><button type="button" className="ow-button ow-secondary" disabled={loading} onClick={load}>{loading?'Consultando…':'Actualizar'}</button></div>{error&&<p className="ow-error" role="alert">{error}</p>}{status?<ServerStatusView status={status}/>:!error&&<p className="ow-help">Consultando…</p>}</section>;
}
export function SecurityEvents({events=[]}){const [all,setAll]=useState(false);const shown=all?events.slice(0,100):events.slice(0,8);return <section className="ow-panel ow-security" aria-labelledby="ow-security-title"><div className="ow-panel-heading"><h2 id="ow-security-title">Eventos de seguridad</h2><span className="ow-help">{events.length} registrados</span></div>{!events.length?<p className="ow-empty-search">Sin eventos de seguridad registrados.</p>:<ul className="ow-security-list">{shown.map(event=><li key={event.id}><span className={'ow-security-type ow-security-'+event.tipo}>{securityLabels[event.tipo]||event.tipo}</span><span>{eventDetail(event)||'—'}</span><time dateTime={event.fecha}>{timeLabel(event.fecha)}</time></li>)}</ul>}{events.length>8&&<button type="button" className="ow-text-button" onClick={()=>setAll(v=>!v)}>{all?'Ver menos':'Ver todos los eventos'}</button>}</section>;}
const downloadJson=(value,name)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=name;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const emptyCompany=()=>({name:'',contactName:'',email:'',whatsapp:'',nit:'',address:'',logo:'',username:'',password:'',adminEmail:'',startDate:today(),endDate:plusMonth(today()),monthlyFee:''});
function formOf(company){return {name:companyName(company),contactName:company.contactName||company.contact||'',email:company.email||'',whatsapp:company.whatsapp||company.phone||'',nit:company.nit||'',address:company.address||'',logo:company.logo||company.logoUrl||'',startDate:companyStart(company),endDate:companyEnd(company),monthlyFee:companyFee(company)};}

export default function OwnerWorkspace({session,data={},onAction,onRetryAction,onRefresh,onProfile,onLogout}){
 const companies=data.companies||[],[selectedId,setSelectedId]=useState(null),[query,setQuery]=useState(''),[modal,setModal]=useState(null),[form,setForm]=useState({}),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[tab,setTab]=useState('details'),[messagePreview,setMessagePreview]=useState(null),[ticketCompanyId,setTicketCompanyId]=useState(null),[formConflict,setFormConflict]=useState(false);
 const company=companies.find(c=>c.id===selectedId),baseline=useRef(''),formRevision=useRef(null);
 const ticketCompany=companies.find(c=>c.id===ticketCompanyId);
 const companyTickets=id=>(data.tickets||[]).filter(ticket=>ticket.companyId===id);
 const ticketBell=target=>{const records=companyTickets(target.id),pending=records.filter(ticket=>ticket.status!=='resolved').length,unread=records.filter(ticket=>ticket.unreadCount>0).length;return <TicketBell count={pending} title={`Tickets de ${companyName(target)}`} aria-label={`Tickets de soporte de ${companyName(target)}: ${pending} pendientes, ${unread} sin leer`} onClick={()=>setTicketCompanyId(target.id)}/>};
 const preview=messagePreview?billingMessagePreview(messagePreview.company,{payment:messagePreview.payment}):null;
 const previewLink=preview?whatsappLink(messagePreview.company.whatsapp||messagePreview.company.phone,messagePreview.kind==='payment'?preview.paymentText:preview.reminderText):'';
 const close=()=>{if(busy)return;if(['create','edit','user','editUser','reset','renew','support','plan','catalog'].includes(modal)&&JSON.stringify(form)!==baseline.current&&!window.confirm('Tienes cambios sin guardar. ¿Quieres descartarlos?'))return;setModal(null);setError('');};
 const field=(key,value)=>setForm(f=>({...f,[key]:value}));
 const users=(data.users||company?.users||[]).filter(u=>company&&u.companyId===company.id);
 const payments=(data.payments||company?.payments||[]).filter(p=>company&&p.companyId===company.id);
 useEffect(()=>{if(selectedId&&!company){setSelectedId(null);setTab('details')}},[companies,selectedId]);
 useEffect(()=>{if(!notice)return;const timeout=setTimeout(()=>setNotice(''),7000);return()=>clearTimeout(timeout)},[notice]);
 const open=(kind,values={})=>{setError('');setNotice('');setFormConflict(false);baseline.current=JSON.stringify(values);formRevision.current=data.revision;setForm(values);setModal(kind)};
 const lastFailure=useRef('');
 const execute=async(action,message)=>{if(busy)return null;const protectedForm=['company.update','company.renew','user.update'].includes(action.type);if(protectedForm&&formConflict){setError('Revisa los datos actuales antes de volver a guardar. Tu formulario sigue sin enviarse.');return null}if(protectedForm&&!Number.isSafeInteger(formRevision.current)){setError('No se pudo identificar la versión del formulario. Ciérralo y vuelve a abrirlo.');return null}setBusy(true);setError('');try{const result=await onAction(protectedForm?{...action,revision:formRevision.current}:action);setModal(null);setFormConflict(false);if(message)setNotice(message);return result}catch(failure){if(protectedForm&&(failure.status===409||failure.code==='REVISION_CONFLICT')){setFormConflict(true);setError('Los datos cambiaron mientras editabas. No se guardó tu formulario y tus cambios siguen aquí. Revisa los datos actuales antes de continuar.')}else setError(failure.message||'No se pudo completar la operación.');lastFailure.current=failure.message||'';return null}finally{setBusy(false)}};
 const reloadForm=async()=>{if(busy||!formConflict)return;if(JSON.stringify(form)!==baseline.current&&!window.confirm('¿Cargar los datos actuales? Se reemplazarán los cambios de este formulario que no se guardaron.'))return;setBusy(true);try{const source=onRefresh?await onRefresh():data;if(!source||!Number.isSafeInteger(source.revision))throw Error('No se pudieron recuperar los datos actuales. Conservamos tu formulario para que vuelvas a intentar.');const fresh=(source.companies||[]).find(item=>item.id===selectedId);let next;if(!fresh)throw Error('Esta empresa ya no está disponible. Conservamos el formulario; ciérralo para volver a la lista.');if(modal==='edit')next=formOf(fresh);else if(modal==='renew')next={...renewalProposal(fresh),paidAt:today(),expired:!companyEnd(fresh)||companyEnd(fresh)<today()};else if(modal==='editUser'){const user=(source.users||[]).find(item=>item.id===form.id&&item.companyId===fresh.id);if(!user)throw Error('El usuario ya no está disponible. Conservamos tu formulario; ciérralo para volver a la lista.');next={id:user.id,username:user.username,name:user.name||user.displayName||'',email:user.email||'',emailVerified:!!user.emailVerified,role:user.role,active:user.active!==false&&user.active!==0};}else return;formRevision.current=source.revision;baseline.current=JSON.stringify(next);setForm(next);setFormConflict(false);setError('');setNotice('Datos actuales recuperados. Revisa el formulario antes de guardar.')}catch(failure){setError(failure.message||'No se pudieron recuperar los datos actuales. Conservamos tu formulario.')}finally{setBusy(false)}};
 const conflictRecovery=formConflict&&<div className="ow-conflict-recovery"><button type="button" className="ow-button ow-secondary" disabled={busy} onClick={reloadForm}>Revisar datos actuales</button><p className="ow-help">Recupera la versión guardada para revisarla antes de continuar. Si tienes cambios sin guardar, se pedirá confirmación para reemplazarlos.</p></div>;
 const act=(type,values={},message)=>execute({type,...values},message);
 const exportCompany=async()=>{const result=await act('company.export',{companyId:company.id});if(!result?.export){if(result)setError('No se recibió el archivo de exportación. Vuelve a intentar.');return}downloadJson(result.export,'scorta-'+(company.slug||'empresa')+'-exportacion-'+today()+'.json');setNotice('Datos exportados. Guarda el archivo en un lugar seguro.')};
 const revokeSessions=async scope=>{const result=await execute(scope==='all'?{type:'sessions.revoke',scope:'all'}:{type:'sessions.revoke',companyId:company.id});if(result)setNotice(`Se cerraron ${Number(result.revoked)||0} ${Number(result.revoked)===1?'sesión':'sesiones'}.${scope==='all'?' Tu sesión actual sigue abierta.':''}`)};
 const companyAction=(type,values={},message)=>act(type,{companyId:company.id,...values},message);
 const submitCompany=e=>{e.preventDefault();if(form.endDate<form.startDate){setError('La fecha final debe ser igual o posterior al inicio.');return}const payload={...form,contact:form.contactName,monthlyFee:Number(form.monthlyFee||0)};delete payload.contactName;if(modal==='create')act('company.create',{form:payload},'Empresa creada. Su acceso ya está preparado.');else companyAction('company.update',{form:payload},'Datos de la empresa actualizados.');};
 const upload=async file=>{setError('');if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){setError('Selecciona un logo PNG, JPG o WebP.');return}if(file.size>500*1024){setError('El logo debe pesar como máximo 500 KB.');return}try{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('No se pudo leer el logo.'));reader.readAsDataURL(file)});field('logo',content)}catch(failure){setError(failure.message)}};
 const copy=async value=>{try{await navigator.clipboard.writeText(value);setNotice('Dirección copiada.')}catch{setError('No fue posible copiar. Selecciona la dirección y cópiala desde tu navegador.')}};
 const openRenew=()=>{const expired=!companyEnd(company)||companyEnd(company)<today();open('renew',{...renewalProposal(company),paidAt:today(),expired});};
 const openMessage=(kind,reference=company,payment=payments[0])=>setMessagePreview({kind,company:reference,payment});
 const submitRenew=async e=>{e.preventDefault();if(form.endDate<form.startDate){setError('Revisa el período de la renovación.');return}const result=await companyAction('company.renew',{form:{startDate:form.startDate,endDate:form.endDate,amount:Number(form.amount),date:form.paidAt}},'Pago registrado y vigencia actualizada.');if(result){const updated=result.companies?.find(c=>c.id===company.id)||{...company,startDate:form.startDate,endDate:form.endDate};const payment=result.payments?.find(p=>p.companyId===company.id)||{amount:Number(form.amount),endDate:form.endDate,date:form.paidAt};openMessage('payment',updated,payment)}};
 const filtered=companies.filter(c=>normalize([companyName(c),c.slug,c.contactName,c.email].join(' ')).includes(normalize(query)));
 const formFields=<><div className="ow-logo-editor">{form.logo?<img src={form.logo} alt="Vista previa del logo"/>:<span><Icon name="company" size={30}/></span>}<div><Field label="Logo de la empresa (opcional)" hint="PNG, JPG o WebP · máximo 500 KB"><input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>upload(e.target.files?.[0])}/></Field>{form.logo&&<button type="button" className="ow-text-button" onClick={()=>field('logo','')}>Quitar logo</button>}</div></div><Field label="Nombre de la empresa"><input value={form.name||''} required maxLength={120} autoComplete="organization" onChange={e=>field('name',e.target.value)} placeholder="Nombre de la empresa"/></Field><div className="ow-form-grid"><Field label="Persona de contacto"><input value={form.contactName||''} required maxLength={120} autoComplete="name" onChange={e=>field('contactName',e.target.value)} placeholder="Nombre del contacto"/></Field><Field label="Correo electrónico (opcional)"><input type="email" value={form.email||''} maxLength={200} autoComplete="email" onChange={e=>field('email',e.target.value)} placeholder="contacto@empresa.com"/></Field></div><div className="ow-form-grid"><Field label="NIT o identificación del negocio (opcional)"><input value={form.nit||''} maxLength={60} onChange={e=>field('nit',e.target.value)} placeholder="Identificación para el ticket de venta"/></Field><Field label="Dirección del negocio (opcional)"><input value={form.address||''} maxLength={300} autoComplete="street-address" onChange={e=>field('address',e.target.value)} placeholder="Dirección del almacén"/></Field></div><Field label="WhatsApp con indicativo" hint="Incluye el código del país, por ejemplo +57."><input type="tel" value={form.whatsapp||''} required maxLength={25} autoComplete="tel" onChange={e=>field('whatsapp',e.target.value)} placeholder="+57 300 123 4567"/></Field>{modal==='create'&&<fieldset className="ow-fieldset"><legend>Primer administrador de la empresa</legend><Field label="Usuario de acceso"><input value={form.username||''} required minLength={3} maxLength={60} autoComplete="off" pattern="[a-zA-Z0-9._-]+" onChange={e=>field('username',e.target.value)} placeholder="Usuario administrador"/></Field><Field label="Correo de recuperación del administrador (opcional)" hint="Es personal de esta cuenta. El usuario lo verifica desde «Mi perfil» con un código."><input type="email" value={form.adminEmail||''} maxLength={254} autoComplete="off" onChange={e=>field('adminEmail',e.target.value)} placeholder="administrador@empresa.com"/></Field><Password value={form.password||''} onChange={e=>field('password',e.target.value)}/></fieldset>}<fieldset className="ow-fieldset"><legend>Contrato</legend><div className="ow-form-grid"><Field label="Fecha de inicio"><input type="date" required value={form.startDate||''} onChange={e=>field('startDate',e.target.value)}/></Field><Field label="Fecha de vencimiento"><input type="date" required min={form.startDate} value={form.endDate||''} onChange={e=>field('endDate',e.target.value)}/></Field></div><Field label="Mensualidad acordada (COP)"><input type="number" required min="0" max="1000000000" step="1" inputMode="numeric" value={form.monthlyFee??''} onChange={e=>field('monthlyFee',e.target.value)}/></Field><p className="ow-help">El acceso incluye el día del vencimiento y se suspende al día siguiente, según la hora de Colombia.</p></fieldset></>;
 return <div className="ow-shell"><header className="ow-topbar"><Brand className="ow-brand"/><div className="ow-account"><button type="button" className="ow-profile" onClick={onProfile}><span>{session?.name||session?.displayName||session?.username||'Propietario'}</span><small>Propietario de SCORTA</small></button><button type="button" className="ow-logout" aria-label="Cerrar sesión" onClick={onLogout}><Icon name="logout"/><span>Cerrar sesión</span></button></div></header><main className="ow-main">{notice&&<div className="ow-notice" role="status"><Icon name="check"/>{notice}<button type="button" className="ow-icon-button" onClick={()=>setNotice('')} aria-label="Cerrar aviso"><Icon name="close"/></button></div>}{error&&!modal&&<p className="ow-error" role="alert">{error}</p>}
 {!company?<><div className="ow-heading"><div><p className="ow-eyebrow">ADMINISTRACIÓN DE SCORTA</p><h1>Empresas</h1><p>Gestiona el acceso de tus clientes.</p></div><div className="ow-button-row"><button type="button" className="ow-button ow-secondary" disabled={busy} onClick={()=>open('revokeAll',{})}>Cerrar todas las sesiones</button><button type="button" className="ow-button ow-primary" onClick={()=>open('create',emptyCompany())}><Icon name="plus"/>Crear nueva empresa</button></div></div><MetricCards metrics={data.metrics}/>{companies.length>0&&<div className="ow-company-toolbar"><span>{companies.length} {companies.length===1?'empresa':'empresas'}</span><label className="ow-search"><Icon name="search"/><input type="search" aria-label="Buscar empresa" placeholder="Buscar empresa" value={query} onChange={e=>setQuery(e.target.value)}/></label><button className="ow-text-button" type="button" onClick={onRefresh} disabled={busy}>Actualizar</button></div>}{!companies.length?<section className="ow-empty"><Icon name="company" size={46}/><h2>Tu primera empresa empieza aquí</h2><p>Crea su perfil, define la vigencia y prepara el acceso de su administrador.</p><button className="ow-button ow-primary" type="button" onClick={()=>open('create',emptyCompany())}>Crear empresa</button></section>:<div className="ow-company-grid">{filtered.map(c=><article className="ow-company-card" key={c.id}><div className="ow-card-tickets"><span>Tickets de soporte{companyTickets(c.id).some(ticket=>ticket.unreadCount>0)&&<b className="sp-support-count">{companyTickets(c.id).filter(ticket=>ticket.unreadCount>0).length} sin leer</b>}</span>{ticketBell(c)}</div><button type="button" className="ow-card-content" onClick={()=>{setSelectedId(c.id);setTab('details');setError('')}} aria-label={'Administrar '+companyName(c)}><div className="ow-card-heading"><Logo company={c}/><div><h2>{companyName(c)}</h2><p>{c.slug||c.code||''}</p></div><Badge company={c}/></div><dl className="ow-card-data"><div><dt>Vencimiento</dt><dd>{dayLabel(companyEnd(c))}</dd></div><div><dt>Vigencia</dt><dd className={daysRemaining(c)!==null&&daysRemaining(c)<=7?'ow-expiry-warning':''}>{datePeriod(c)}</dd></div>{c.usage&&<><div><dt>Último acceso</dt><dd>{c.usage.lastLoginAt?timeLabel(c.usage.lastLoginAt):'Sin accesos'}</dd></div><div><dt>Última venta</dt><dd>{c.usage.lastSaleAt?dayLabel(c.usage.lastSaleAt):'Sin ventas'}</dd></div><div><dt>Ventas 7 días</dt><dd>{usageOf(c).sales7d}{usageOf(c).idle&&<span className="ow-badge ow-badge-idle">Sin uso</span>}</dd></div></>}</dl></button><div className="ow-card-url"><Icon name="link" size={17}/>{c.url?<a href={c.url} target="_blank" rel="noreferrer">{c.url.replace(/^https?:\/\//,'')}</a>:<span>Dirección disponible al guardar</span>}{c.url&&<button type="button" className="ow-icon-button" aria-label={'Copiar dirección de '+companyName(c)} onClick={()=>copy(c.url)}><Icon name="copy" size={17}/></button>}</div><button type="button" className="ow-card-manage" onClick={()=>{setSelectedId(c.id);setTab('details');setError('')}}>Administrar empresa</button></article>)}</div>}{companies.length>0&&!filtered.length&&<p className="ow-empty-search">No encontramos empresas con esa búsqueda.</p>}{Array.isArray(data.securityEvents)&&<><ServerStatus/><SecurityEvents events={data.securityEvents}/></>}</>:<><button type="button" className="ow-back ow-text-button" onClick={()=>{setSelectedId(null);setError('');setNotice('')}}><Icon name="back"/>Empresas</button><div className="ow-heading ow-detail-heading"><div className="ow-detail-name"><Logo company={company}/><div><h1>{companyName(company)}</h1><p>{company.contactName||company.contact||'Contacto por registrar'}</p></div><Badge company={company}/><div className="ow-detail-support-button">{ticketBell(company)}</div></div></div><nav className="ow-detail-tabs" aria-label="Administración de empresa">{[['details','Datos y acceso'],['users','Usuarios y permisos'],['payments','Pagos y renovaciones']].map(([id,label])=><button type="button" key={id} aria-current={tab===id?'page':undefined} onClick={()=>{setTab(id);setError('')}}>{label}{id==='users'&&<span>{users.length}</span>}</button>)}</nav>
 {tab==='details'&&<div className="ow-detail-grid"><section className="ow-panel"><div className="ow-panel-heading"><h2>Datos de la empresa</h2><button type="button" className="ow-button ow-secondary" onClick={()=>open('edit',formOf(company))}>Editar</button></div><dl className="ow-detail-data"><div><dt>Persona de contacto</dt><dd>{company.contactName||company.contact||'Sin registrar'}</dd></div><div><dt>Correo</dt><dd>{company.email?<a href={'mailto:'+company.email}>{company.email}</a>:'Sin registrar'}</dd></div><div><dt>WhatsApp</dt><dd>{company.whatsapp||company.phone||'Sin registrar'}</dd></div><div><dt>NIT / identificación</dt><dd>{company.nit||'Sin registrar'}</dd></div><div><dt>Dirección del negocio</dt><dd>{company.address||'Sin registrar'}</dd></div><div><dt>Inicio del contrato</dt><dd>{dayLabel(companyStart(company))}</dd></div><div><dt>Vencimiento</dt><dd>{dayLabel(companyEnd(company))}<small className={daysRemaining(company)<=7?'ow-expiry-warning':''}>{datePeriod(company)}</small></dd></div><div><dt>Mensualidad acordada</dt><dd>{money(companyFee(company))}</dd></div></dl></section><div className="ow-panel-stack"><section className="ow-panel"><h2>Catálogo público</h2><p>La tienda de tu cliente, con sus productos, logo y colores.</p><a className="ow-button ow-secondary" href={'/catalogo/'+encodeURIComponent(company.slug)} target="_blank" rel="noreferrer">Ver catálogo</a><button type="button" className="ow-button ow-secondary" onClick={()=>open('catalog',{})}>Configurar catálogo</button></section><PlanSummary company={company} onEdit={()=>open('plan',planForm(company))}/><section className="ow-panel"><h2>Acceso y soporte</h2><p className="ow-help">Dirección de la empresa</p><div className="ow-url-line">{company.url?<a href={company.url} target="_blank" rel="noreferrer">{company.url}</a>:<span>Sin dirección</span>}{company.url&&<button type="button" className="ow-icon-button" aria-label="Copiar dirección" onClick={()=>copy(company.url)}><Icon name="copy"/></button>}</div><Badge company={company}/><p className="ow-help">Una suspensión manual se conserva aunque registres un pago.</p><div className="ow-button-row"><button type="button" className="ow-button ow-secondary" disabled={!manualBlock(company)||busy} onClick={()=>open('enable',{})}>Habilitar</button><button type="button" className="ow-button ow-secondary" disabled={manualBlock(company)||busy} onClick={()=>open('disable',{})}>Inhabilitar</button></div><button type="button" className="ow-button ow-support" onClick={()=>open('support',{reason:''})}>Acceder como soporte</button><button type="button" className="ow-button ow-secondary" disabled={busy} onClick={()=>open('revokeCompany',{})}>Cerrar sesiones de la empresa</button>{company.usage&&<dl className="ow-detail-data ow-usage"><div><dt>Último acceso</dt><dd>{company.usage.lastLoginAt?timeLabel(company.usage.lastLoginAt):'Sin accesos'}</dd></div><div><dt>Última venta</dt><dd>{company.usage.lastSaleAt?dayLabel(company.usage.lastSaleAt):'Sin ventas'}</dd></div><div><dt>Ventas de los últimos 7 días</dt><dd>{usageOf(company).sales7d}{usageOf(company).idle&&<span className="ow-badge ow-badge-idle">Sin uso</span>}</dd></div></dl>}</section><section className="ow-panel"><h2>Datos de la empresa</h2><p className="ow-help">Descarga un archivo JSON con inventario, ventas, clientes, usuarios (sin contraseñas), pagos y tickets.{company.exportedAt?' Última exportación: '+timeLabel(company.exportedAt)+'.':''}</p><button type="button" className="ow-button ow-secondary" disabled={busy} onClick={exportCompany}>{busy?'Preparando…':'Exportar datos'}</button></section><section className="ow-panel ow-danger-panel"><h2>Eliminar empresa</h2><p>Se eliminarán sus usuarios, inventario, ventas, servicios e historial. Esta acción requiere confirmación.</p><button type="button" className="ow-button ow-danger" onClick={()=>open('delete',{confirmation:''})}>Eliminar empresa</button><h3>Borrar datos definitivamente</h3><p>Al terminar el contrato, borra todos los datos de la empresa y conserva solo un certificado con los conteos. Primero debes exportarlos.</p><button type="button" className="ow-button ow-danger" disabled={busy||!company.exportedAt} onClick={()=>open('purge',{confirmation:'',understood:false})}>Borrar datos definitivamente</button>{!company.exportedAt&&<p className="ow-help">Se habilita después de «Exportar datos».</p>}</section></div></div>}
 {tab==='users'&&<section className="ow-panel"><div className="ow-panel-heading"><div><h2>Usuarios y permisos</h2><p className="ow-help">Solo el propietario de SCORTA crea cuentas y asigna roles.</p></div><button type="button" className="ow-button ow-primary" onClick={()=>open('user',{name:'',username:'',email:'',password:'',role:'vendedor'})}><Icon name="plus"/>Crear usuario</button></div>{!users.length?<p className="ow-empty-search">Esta empresa todavía no tiene usuarios.</p>:<div className="ow-table-wrap"><table className="ow-table"><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Último cambio de contraseña</th><th>Acciones</th></tr></thead><tbody>{users.map(u=><tr key={u.id||u.username}><td data-label="Usuario"><strong>{u.name||u.displayName||u.username}</strong><small>{u.username}</small><small>{u.email?`${u.email} · ${u.emailVerified?'Verificado':'Pendiente de verificar'}`:'Sin correo de recuperación'}</small></td><td data-label="Rol">{roleLabel(u.role)}</td><td data-label="Estado"><span className={'ow-badge '+(u.active===false||u.active===0?'ow-badge-disabled':'ow-badge-active')}>{u.active===false||u.active===0?'Inactivo':'Activo'}</span></td><td data-label="Contraseña">{timeLabel(u.passwordChangedAt||u.updatedPasswordAt||u.createdAt)}</td><td data-label="Acciones"><div className="ow-user-actions"><button className="ow-text-button" type="button" onClick={()=>open('editUser',{id:u.id,username:u.username,name:u.name||u.displayName||'',email:u.email||'',emailVerified:!!u.emailVerified,role:u.role,active:u.active!==false&&u.active!==0})}>Editar</button><button className="ow-text-button" type="button" onClick={()=>open('reset',{id:u.id,username:u.username,password:''})}>Restablecer contraseña</button></div></td></tr>)}</tbody></table></div>}<p className="ow-help ow-permission-note">Administradores: todos los módulos de su empresa. Vendedores: Nueva venta, Inventario de consulta y registro de mano de obra en Taller. Una empresa puede tener varios administradores.</p></section>}
 {tab==='payments'&&<section className="ow-panel"><div className="ow-panel-heading"><div><h2>Pagos y renovaciones</h2><p className="ow-help">Cada registro conserva el importe y la vigencia contratada.</p></div><button type="button" className="ow-button ow-primary" onClick={openRenew}>Registrar pago y renovar</button></div>{!payments.length?<p className="ow-empty-search">No se han registrado renovaciones para esta empresa.</p>:<div className="ow-table-wrap"><table className="ow-table"><thead><tr><th>Fecha</th><th>Importe</th><th>Vencimiento anterior</th><th>Nuevo vencimiento</th><th>Registrado por</th></tr></thead><tbody>{payments.map((payment,index)=><tr key={payment.id||index}><td data-label="Fecha">{dayLabel(payment.paidAt||payment.date||payment.fecha||payment.createdAt)}</td><td data-label="Importe">{money(payment.amount||payment.importe)}</td><td data-label="Vencimiento anterior">{dayLabel(payment.previousEndDate)}</td><td data-label="Nuevo vencimiento">{dayLabel(payment.endDate||payment.newEndDate||payment.periodEnd)}</td><td data-label="Registrado por">{payment.actor||payment.username||payment.usuario||'Propietario'}</td></tr>)}</tbody></table></div>}<section className="ow-communications" aria-labelledby="ow-communications-title"><div className="ow-communication-heading"><h3 id="ow-communications-title">Avisos por WhatsApp</h3><span className="ow-connection-status">Envío automático pendiente de conectar</span></div><p className="ow-help">Vista previa de los mensajes que recibirá el contacto de la empresa. En esta versión no se envían mensajes.</p><dl className="ow-communication-data"><div><dt>WhatsApp de la empresa</dt><dd>{company.whatsapp||'Sin registrar'}</dd></div><div><dt>Fecha prevista del recordatorio</dt><dd>{dayLabel(billingMessagePreview(company).reminderDate)}</dd></div><div><dt>Vencimiento vigente</dt><dd>{dayLabel(companyEnd(company))}</dd></div></dl><div className="ow-message-actions"><button type="button" className="ow-button ow-secondary" onClick={()=>openMessage('reminder')}>Vista previa del recordatorio</button><button type="button" className="ow-button ow-secondary" disabled={!payments.length} onClick={()=>openMessage('payment')}>Vista previa de confirmación de pago</button></div><p className="ow-help ow-communication-note">Se prevé un recordatorio tres días antes del vencimiento vigente, una sola vez por período. Si registras una renovación antes de esa fecha, se reemplaza el aviso del período anterior.</p>{!payments.length&&<p className="ow-help">La confirmación se previsualiza después de registrar el primer pago.</p>}</section></section>}
 </>}
 <p className="ow-footer">SCORTA · Administración de empresas</p></main>
 {ticketCompany&&<SupportTickets owner tickets={companyTickets(ticketCompany.id)} session={session} company={ticketCompany} onAction={onAction} onRetryAction={onRetryAction} onClose={()=>setTicketCompanyId(null)}/>}
 {(modal==='create'||modal==='edit')&&<Modal title={modal==='create'?'Crear nueva empresa':'Editar empresa'} busy={busy} onClose={close} footer={<><button type="button" className="ow-button ow-secondary" disabled={busy} onClick={close}>Cancelar</button><button type="submit" form="ow-company-form" className="ow-button ow-primary" disabled={busy||(modal==='edit'&&formConflict)}>{busy?'Guardando…':modal==='create'?'Crear empresa':'Guardar cambios'}</button></>}><form id="ow-company-form" onSubmit={submitCompany}>{formFields}{error&&<p className="ow-error" role="alert">{error}</p>}{conflictRecovery}</form></Modal>}
 {modal==='plan'&&company&&<Modal title="Plan y límites" busy={busy} onClose={close} footer={<><button type="button" className="ow-button ow-secondary" disabled={busy} onClick={close}>Cancelar</button><button type="submit" form="ow-plan-form" className="ow-button ow-primary" disabled={busy}>{busy?'Guardando…':'Guardar plan'}</button></>}><form id="ow-plan-form" onSubmit={e=>{e.preventDefault();const values={};for(const key of ['maxUsers','maxProducts','maxPhotos']){const raw=String(form[key]??'').trim();if(raw===''){values[key]=null;continue}const number=Number(raw);if(!Number.isSafeInteger(number)||number<0){setError('Usa números enteros o deja el campo vacío para no limitar.');return}values[key]=number}companyAction('company.plan',{form:{...values,features:form.features}},'Plan actualizado. Los límites aplican desde ahora.')}}>
  <p className="ow-help">Deja vacío un límite para no restringirlo. Si la empresa ya supera un límite, conserva lo que tiene pero no puede agregar más.</p>
  <div className="ow-form-grid">{Object.entries(PLAN_LIMIT_LABELS).map(([key,label])=><Field key={key} label={'Máximo de '+label} hint={'En uso: '+(Number(company.usage?.[{maxUsers:'users',maxProducts:'products',maxPhotos:'photos'}[key]])||0)}><input type="number" inputMode="numeric" min="0" step="1" value={form[key]??''} placeholder="Sin límite" onChange={e=>field(key,e.target.value)}/></Field>)}</div>
  <fieldset className="ow-plan-features"><legend>Funciones opcionales</legend>{PLAN_FEATURES.map(([key,label])=><label key={key} className="ow-check"><input type="checkbox" checked={(form.features||[]).includes(key)} onChange={e=>field('features',e.target.checked?[...(form.features||[]),key]:(form.features||[]).filter(item=>item!==key))}/><span>{label}</span></label>)}</fieldset>
  <p className="ow-help">Al quitar una función, la empresa deja de ver ese módulo y no puede crear documentos nuevos; los que están en curso se pueden terminar. Quitar el IVA lo desactiva en sus ventas.</p>
  {error&&<p className="ow-error" role="alert">{error}</p>}</form></Modal>}
 {modal==='renew'&&company&&<Modal title="Registrar pago y renovar" busy={busy} onClose={close} footer={<><button className="ow-button ow-secondary" type="button" onClick={close} disabled={busy}>Cancelar</button><button className="ow-button ow-primary" type="submit" form="ow-renew-form" disabled={busy||formConflict}>{busy?'Registrando…':'Confirmar renovación'}</button></>}><form id="ow-renew-form" onSubmit={submitRenew}><div className="ow-renew-current"><span>Vencimiento actual</span><strong>{dayLabel(companyEnd(company))}</strong></div><p className="ow-help">{form.expired?'El nuevo período comienza en la fecha que elijas.':'La renovación anticipada conserva los días ya pagados.'}</p><div className="ow-form-grid"><Field label="Inicio del período"><input type="date" required value={form.startDate} onChange={e=>{const value=e.target.value;setForm(f=>({...f,startDate:value,endDate:value?plusMonth(value):''}))}}/></Field><Field label="Nuevo vencimiento"><input type="date" required min={form.startDate} value={form.endDate} onChange={e=>field('endDate',e.target.value)}/></Field><Field label="Fecha del pago"><input type="date" required value={form.paidAt} onChange={e=>{const value=e.target.value;setForm(f=>({...f,paidAt:value,...(f.expired&&value?{startDate:value,endDate:plusMonth(value)}:{})}))}}/></Field><Field label="Importe recibido (COP)"><input type="number" required min="0" max="1000000000" step="1" value={form.amount} onChange={e=>field('amount',e.target.value)}/></Field></div>{manualBlock(company)&&<p className="ow-warning"><Icon name="warning"/>La empresa tiene una suspensión manual. El pago no la habilitará; podrás hacerlo desde Datos y acceso.</p>}<div className="ow-renew-preview"><span>Nuevo acceso válido hasta</span><strong>{dayLabel(form.endDate)}</strong></div>{error&&<p className="ow-error" role="alert">{error}</p>}{conflictRecovery}</form></Modal>}
 {(modal==='user'||modal==='editUser')&&company&&<Modal title={modal==='user'?'Crear usuario':'Editar usuario'} busy={busy} onClose={close} footer={<><button className="ow-button ow-secondary" type="button" onClick={close} disabled={busy}>Cancelar</button><button className="ow-button ow-primary" type="submit" form="ow-user-form" disabled={busy||(modal==='editUser'&&formConflict)}>{busy?'Guardando…':'Guardar usuario'}</button></>}><form id="ow-user-form" onSubmit={e=>{e.preventDefault();companyAction(modal==='user'?'user.create':'user.update',{userId:form.id,form:{...form}},modal==='user'?'Usuario creado.':'Usuario actualizado.')}}><Field label="Nombre de la persona"><input required maxLength={120} value={form.name} onChange={e=>field('name',e.target.value)} autoComplete="name"/></Field><Field label="Usuario de acceso"><input required minLength={3} maxLength={60} pattern="[a-zA-Z0-9._-]+" value={form.username} onChange={e=>field('username',e.target.value)} autoComplete="off" disabled={modal==='editUser'}/></Field><Field label="Correo de recuperación (opcional)" hint={form.emailVerified?'Correo verificado. Si lo cambias, deberá verificarse de nuevo.':'Pendiente de verificar: el usuario lo confirma desde «Mi perfil» con un código.'}><input type="email" maxLength={254} value={form.email||''} autoComplete="off" onChange={e=>setForm(f=>({...f,email:e.target.value,emailVerified:false}))} placeholder="usuario@empresa.com"/></Field><Field label="Rol"><select value={form.role} onChange={e=>field('role',e.target.value)}><option value="admin">Administrador de empresa</option><option value="vendedor">Vendedor</option></select></Field>{modal==='user'?<Password value={form.password} onChange={e=>field('password',e.target.value)}/>:<Field label="Estado del acceso"><select value={form.active?'active':'inactive'} onChange={e=>field('active',e.target.value==='active')}><option value="active">Activo</option><option value="inactive">Inactivo</option></select></Field>}<p className="ow-help">Cada persona debe utilizar su propia cuenta para identificar quién registra las operaciones.</p>{error&&<p className="ow-error" role="alert">{error}</p>}{conflictRecovery}</form></Modal>}
 {modal==='reset'&&company&&<Modal title="Restablecer contraseña" busy={busy} onClose={close} footer={<><button className="ow-button ow-secondary" type="button" onClick={close} disabled={busy}>Cancelar</button><button className="ow-button ow-primary" type="submit" form="ow-reset-form" disabled={busy}>{busy?'Guardando…':'Restablecer contraseña'}</button></>}><form id="ow-reset-form" onSubmit={e=>{e.preventDefault();companyAction('user.reset',{userId:form.id,username:form.username,form:{password:form.password}},'Contraseña restablecida. Las sesiones anteriores del usuario se han cerrado.')}}><p>Asigna una nueva contraseña a <strong>{form.username}</strong>. La contraseña anterior dejará de funcionar.</p><Password label="Nueva contraseña" value={form.password} onChange={e=>field('password',e.target.value)}/>{error&&<p className="ow-error" role="alert">{error}</p>}</form></Modal>}
 {(modal==='enable'||modal==='disable')&&company&&<Modal title={modal==='enable'?'Habilitar empresa':'Inhabilitar empresa'} busy={busy} onClose={close} footer={<><button className="ow-button ow-secondary" type="button" onClick={close} disabled={busy}>Cancelar</button><button className="ow-button ow-primary" type="button" disabled={busy} onClick={()=>companyAction('company.access',{enabled:modal==='enable',form:{enabled:modal==='enable'}},modal==='enable'?'Suspensión manual retirada. Se aplicará la vigencia del contrato.':'Empresa inhabilitada. Sus datos se conservan.')}>{busy?'Guardando…':modal==='enable'?'Habilitar empresa':'Inhabilitar empresa'}</button></>}><p>{modal==='enable'?'Se retirará la suspensión manual de':'Se bloqueará el acceso de todos los usuarios de'} <strong>{companyName(company)}</strong>.</p><p className="ow-help">{modal==='enable'?'El contrato debe estar vigente para que los usuarios puedan ingresar.':'El inventario, las ventas y el historial se conservarán.'}</p>{error&&<p className="ow-error" role="alert">{error}</p>}</Modal>}
 {modal==='delete'&&company&&<Modal title="Eliminar empresa" busy={busy} onClose={close} footer={<><button className="ow-button ow-secondary" type="button" onClick={close} disabled={busy}>Conservar empresa</button><button className="ow-button ow-danger-solid" type="button" disabled={busy||form.confirmation.trim()!==companyName(company)} onClick={async()=>{const result=await companyAction('company.delete',{confirmation:form.confirmation,form:{confirmation:form.confirmation}},'Empresa eliminada.');if(result)setSelectedId(null)}}>{busy?'Eliminando…':'Eliminar definitivamente'}</button></>}><p>Se eliminará <strong>{companyName(company)}</strong> con sus usuarios, productos, existencias, ventas, servicios, pagos e historial.</p><p className="ow-warning">Esta acción no se puede deshacer desde la aplicación.</p><Field label={'Escribe '+companyName(company)+' para confirmar'}><input value={form.confirmation} onChange={e=>field('confirmation',e.target.value)} autoComplete="off"/></Field>{error&&<p className="ow-error" role="alert">{error}</p>}</Modal>}
 {(modal==='revokeAll'||modal==='revokeCompany'&&company)&&<Modal title={modal==='revokeAll'?'Cerrar todas las sesiones':'Cerrar sesiones de la empresa'} busy={busy} onClose={close} footer={<><button className="ow-button ow-secondary" type="button" onClick={close} disabled={busy}>Cancelar</button><button className="ow-button ow-danger-solid" type="button" disabled={busy} onClick={()=>revokeSessions(modal==='revokeAll'?'all':'company')}>{busy?'Cerrando…':'Cerrar sesiones'}</button></>}><p>{modal==='revokeAll'?<>Se cerrarán las sesiones abiertas de <strong>todas las empresas</strong> y tus otras sesiones de propietario. Tu sesión actual se conserva.</>:<>Se cerrarán todas las sesiones abiertas de <strong>{companyName(company)}</strong>, incluido el acceso de soporte.</>}</p><p className="ow-help">Los usuarios deberán volver a ingresar. Úsalo si sospechas de un acceso indebido.</p>{error&&<p className="ow-error" role="alert">{error}</p>}</Modal>}
 {modal==='purge'&&company&&<Modal title="Borrar datos definitivamente" busy={busy} onClose={close} footer={<><button className="ow-button ow-secondary" type="button" onClick={close} disabled={busy}>Conservar datos</button><button className="ow-button ow-danger-solid" type="button" disabled={busy||!form.understood||form.confirmation.trim()!==companyName(company)} onClick={async()=>{if(!window.confirm('Última confirmación: se borrarán todos los datos de '+companyName(company)+'. ¿Continuar?'))return;const result=await companyAction('company.purge',{form:{confirmation:form.confirmation.trim()}},'Datos borrados. El certificado de borrado quedó en la auditoría.');if(result)setSelectedId(null)}}>{busy?'Borrando…':'Borrar definitivamente'}</button></>}><p>Se borrarán <strong>{companyName(company)}</strong>, sus usuarios, inventario, ventas, clientes, pagos y tickets. Solo quedará un certificado con los conteos.</p><p className="ow-help">Última exportación: {company.exportedAt?timeLabel(company.exportedAt):'sin exportar'}.</p><label className="ow-check"><input type="checkbox" checked={!!form.understood} onChange={e=>field('understood',e.target.checked)}/><span>Entiendo que esta acción no se puede deshacer.</span></label><Field label={'Escribe '+companyName(company)+' para confirmar'}><input value={form.confirmation} onChange={e=>field('confirmation',e.target.value)} autoComplete="off"/></Field>{error&&<p className="ow-error" role="alert">{error}</p>}</Modal>}
 {modal==='catalog'&&company&&<Modal title="Configurar catálogo" busy={busy} onClose={close}><CatalogSettings company={company} revision={data.revision} busy={busy} onDirty={()=>field('catalogDirty',true)} onSave={async action=>{lastFailure.current='';const result=await execute(action,'Catálogo actualizado.');if(!result)throw Error(lastFailure.current||'No se pudo guardar. Revisa los datos e intenta de nuevo.')}}/></Modal>}
 {modal==='support'&&company&&<Modal title="Acceder como soporte" busy={busy} onClose={close} footer={<><button className="ow-button ow-secondary" type="button" onClick={close} disabled={busy}>Cancelar</button><button className="ow-button ow-primary" type="submit" form="ow-support-form" disabled={busy}>{busy?'Abriendo…':'Iniciar soporte'}</button></>}><form id="ow-support-form" onSubmit={e=>{e.preventDefault();companyAction('support.start',{form:{motivo:form.reason}},'Acceso de soporte iniciado.')}}><p>Vas a ingresar a <strong>{companyName(company)}</strong> con tu identidad de propietario.</p><Field label="Motivo de la solicitud del cliente"><textarea required minLength={5} maxLength={500} value={form.reason} onChange={e=>field('reason',e.target.value)} placeholder="Describe el ajuste que solicitó el cliente"/></Field><p className="ow-help">Las operaciones quedarán identificadas como soporte y serán visibles para el cliente en Movimientos.</p>{error&&<p className="ow-error" role="alert">{error}</p>}</form></Modal>}
 {messagePreview&&preview&&<Modal title={messagePreview.kind==='payment'?'Vista previa de confirmación de pago':'Vista previa del recordatorio'} onClose={()=>setMessagePreview(null)} footer={<>{previewLink?<a className="ow-button ow-primary ow-whatsapp-link" href={previewLink} target="_blank" rel="noopener noreferrer">Enviar por WhatsApp</a>:<span className="ow-help">Registra el WhatsApp de la empresa para enviarlo.</span>}<button className="ow-button ow-secondary" type="button" onClick={()=>setMessagePreview(null)}>Cerrar vista previa</button></>}><span className="ow-connection-status">Vista previa · no enviado</span><dl className="ow-message-meta"><div><dt>Empresa</dt><dd>{companyName(messagePreview.company)}</dd></div><div><dt>Destino</dt><dd>{messagePreview.company.whatsapp||'WhatsApp de la empresa pendiente de registrar'}</dd></div>{messagePreview.kind==='reminder'&&<div><dt>Fecha prevista</dt><dd>{dayLabel(preview.reminderDate)}</dd></div>}</dl><blockquote className="ow-message-preview">{messagePreview.kind==='payment'?preview.paymentText:preview.reminderText}</blockquote><p className="ow-help">El día {dayLabel(messagePreview.kind==='payment'?preview.paymentEnd:preview.endDate)} está incluido en el servicio. El bloqueo por vencimiento comenzaría el {dayLabel(messagePreview.kind==='payment'?shiftDay(preview.paymentEnd,1):preview.blockDate)}, según la hora de Colombia.</p><p className="ow-help ow-message-pending">El mensaje no ha sido enviado. «Enviar por WhatsApp» abre WhatsApp con el texto listo para que lo revises y lo envíes tú. La conexión automática con WhatsApp Business queda para una etapa posterior.</p></Modal>}
 </div>;
}
